$$\begin{array}{l}
  {R_{n} = {f(x_{1})\Delta x + f(x_{2})\Delta x + \cdots + f(x_{n})\Delta x}} \\
  {\phantom{R_{n}} = {e^{- x_{1}}\Delta x + e^{- x_{2}}\Delta x + \cdots + e^{- x_{n}}{\Delta x}}} \\
  {\phantom{R_{n}} = {e^{- {2 \slash n}}\left( \frac{2}{n} \right) + e^{- {4 \slash n}}\left( \frac{2}{n} \right) + \cdots + e^{- {{2n} \slash n}}\left( \frac{2}{n}) \right.}}
  \end{array}$$

$$\begin{array}{l}
  {A{= M_{10} = f(0.1)\Delta x + f(0.3)\Delta x + f(0.5)\Delta x + \cdots + f(1.9)\Delta x}} \\
  {\phantom{A}{= 0.2(e^{- 0.1} + e^{- 0.3} + e^{- 0.5} + \cdots + e^{- 1.9}) \approx 0.8632}}
  \end{array}$$

$$\begin{array}{l}
  {R_{6} = {\underset{i=1}{\overset{6}{\sum}}f{\left( x_{i} \right)}\Delta x}} \\
  {\phantom{R_{6}} = {f(0.5)\Delta x + f(1.0)\Delta x + f(1.5)\Delta x + f(2.0)\Delta x + f(2.5)\Delta x + f(3.0)\Delta x}} \\
