$$\begin{array}{l}
  {{\int_{a}^{b}{\lbrack f(x) + g(x)\rbrack\mathit{dx}}} = {\lim\limits_{n\rightarrow\infty}\underset{i=1}{\overset{n}{\sum}}{\lbrack f(x_{i})} + g(x_{i})\rbrack\Delta x}} \\
  {\phantom{\int_{a}^{b}{\lbrack f(x) + g(x)\rbrack\mathit{dx}}} = {\lim\limits_{n\rightarrow\infty}\left\lbrack {\underset{i=1}{\overset{n}{\sum}}{f(x_{i})\Delta x + \underset{i=1}{\overset{n}{\sum}}{g(x_{i})\Delta x}}} \right\rbrack}} \\
  {\phantom{\int_{a}^{b}{\lbrack f(x) + g(x)\rbrack\mathit{dx}}} = {\lim\limits_{n\rightarrow\infty}{\underset{i=1}{\overset{n}{\sum}}{f(x_{i})\Delta x + \lim\limits_{n\rightarrow\infty}}\underset{i=1}{\overset{n}{\sum}}{g(x_{i})\Delta x}}}} \\
  {\phantom{\int_{a}^{b}{\lbrack f(x) + g(x)\rbrack\mathit{dx}}} = {\int_{a}^{b}{f(x)\mathit{dx} + {\int_{a}^{b}{g(x)\mathit{dx}}}}}}
  \end{array}$$

statement.paragraph:
            $${\int_{0}^{\pi}f}(x)\mathit{dx}$$ where $$f(x) = \left\{ \begin{array}{l}
{\sin x{if}0 \leqslant x < {\pi \slash 2}} \\
{\cos x{if}\pi \slash 2 \leqslant x \leqslant \pi}
\end{array} \right.$$

            $${\int_{- 2}^{2}f}(x)\mathit{dx}$$ where $$f(x) = \left\{ \begin{array}{l}
{2\mspace{45mu}{if} - 2 \leqslant x \leqslant 0} \\
{4 - x^{2}{if}0 < x \leqslant 2}
\end{array} \right.$$

paragraph.math:
$$\begin{array}{l}
  {{\int_{1}^{9}\frac{2t^{2} + t^{2}\sqrt{t} - 1}{t^{2}}}\mathit{dt} = \int_{1}^{9}{({2 + t^{1 \slash 2} - t^{- 2}})}\mathit{dt}} \\
  {\phantom{{\int_{1}^{9}\frac{2t^{2} + t^{2}\sqrt{t} - 1}{t^{2}}}\mathit{dt}} = 2t + \frac{t^{3 \slash 2}}{\frac{3}{2}} - \left. \frac{t^{- 1}}{- 1} \right\rbrack_{1}^{9} = 2t + \frac{2}{3}t^{3 \slash 2} + \left. \frac{1}{t} \right\rbrack_{1}^{9}} \\
  {\phantom{{\int_{1}^{9}\frac{2t^{2} + t^{2}\sqrt{t} - 1}{t^{2}}}\mathit{dt}} = \left( {2 \cdot 9 + \frac{2}{3} \cdot 9^{3 \slash 2} + \frac{1}{9}} \right) - \left( {2 \cdot 1 + \frac{2}{3} \cdot 1^{3 \slash 2} + \frac{1}{1}} \right)} \\
  {\phantom{{\int_{1}^{9}\frac{2t^{2} + t^{2}\sqrt{t} - 1}{t^{2}}}\mathit{dt}} = 18 + 18 + \frac{1}{9} - 2 - \frac{2}{3} - 1 = 32\frac{4}{9}}
  \end{array}$$

$$\begin{array}{l}
  {{displacement} = \int_{t_{1}}^{t_{2}}v(t)\mathit{dt} = A_{1} - A_{2} + A_{3}} \\
  {{distance} = {\int_{t_{1}}^{t_{2}}{\left| {v(t)} \right|\mathit{dt} = A_{1} + A_{2} + A_{3}}}_{}}
  \end{array}$$

$$\begin{array}{l}
  {{\int{\tan x\mathit{dx}}} = {\int{\frac{\sin x}{\cos x}\mathit{dx}}} = - {\int{\frac{1}{u}\mathit{du}}}} \\
  {\phantom{\int{\tan x\mathit{dx}}} = - \ln|u| + C = - \ln\left| {\cos x} \right| + C}
  \end{array}$$
